/* MUTANT: one refusal broken on purpose. Generated by mut/make.py. */
/* ov-geo - what <ov-geomap> and <ov-tactical> share: the sphere, the country
 * outlines, and the rules for a reported position.
 *
 * Not an element. Both maps import it, so the two cannot disagree about when a
 * fix is stale or whether a route is being flown.
 *
 * ── A FIX ─────────────────────────────────────────────────────────────────
 *
 * ⭐ AN ARC MUST NOT LOOK LIKE A LIVE TRACK UNLESS SOMETHING IS MOVING. A
 * reported position is judged, never assumed:
 *
 *   plan     no position at all: a route drawn still and dashed
 *   undated  a position with no time: it cannot be fresh or stale
 *   ahead    a time later than this clock: nothing about it can be trusted
 *   stale    older than `fresh` seconds: hollow, and it says how old
 *   held     fresh, but not moved since the previous report (or only one
 *            report so far, so there is nothing to have moved from)
 *   live     fresh AND moved: the only state that may animate
 *
 * 🔴 NO FIGURE THAT STOPS COUNTING. "FIX 3 S" freezes the moment reports stop,
 * and a map that shows 3 s for as long as the feed is dead is lying in the one
 * case that matters. A fresh fix prints its clock time (UTC), which is true
 * forever. A stale one prints its time for two minutes and then whole minutes,
 * and the map sets one timer for the next moment any of those words changes.
 *
 * ── COUNTRIES ─────────────────────────────────────────────────────────────
 *
 * 🔴 OPT-IN. The outlines are 19.5 kB gzipped and live in ov-countries.js,
 * which `import 'overscan'` does not load. Give them to every map at once with
 * setCountries(data), to one map with map.countriesData = data, or name the
 * module on the element (countries="…/ov-countries.js") and it is imported
 * when needed. Asked for and absent is SAID, never drawn as an empty ocean:
 * missing, loading, failed to load, and unreadable are four different words.
 */

export const R = 6371.0088;                     // mean Earth radius, km
export const rad = (d) => (d * Math.PI) / 180;
export const deg = (r) => (r * 180) / Math.PI;
export const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
export const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
export const norm = (a) => { const n = Math.hypot(a[0], a[1], a[2]); return [a[0] / n, a[1] / n, a[2] / n]; };
export const angle = (a, b) => Math.atan2(Math.hypot(...cross(a, b)), dot(a, b));

export function toVec(lat, lon) {
  const p = rad(lat), l = rad(lon);
  return [Math.cos(p) * Math.cos(l), Math.cos(p) * Math.sin(l), Math.sin(p)];
}
export const toLL = ([x, y, z]) => ({ lat: deg(Math.atan2(z, Math.hypot(x, y))), lon: deg(Math.atan2(y, x)) });

/* A position is placeable only with two finite numbers. null, undefined, ''
 * and 'north' are not coordinates; Number(null) is 0, which is the Gulf of
 * Guinea, and that is how a missing fix gets drawn off Africa. */
export function valid(p) {
  if (!p || typeof p !== 'object') return false;
  const ok = (v) => (typeof v === 'number' || (typeof v === 'string' && v.trim() !== '')) && Number.isFinite(Number(v));
  return ok(p.lat) && ok(p.lon) && Math.abs(Number(p.lat)) <= 90;
}
export const ll = (p) => ({ lat: Number(p.lat), lon: Number(p.lon) });

export function slerp(a, b, t) {
  const w = angle(a, b);
  if (w < 1e-12) return a;
  const s = Math.sin(w), ka = Math.sin((1 - t) * w) / s, kb = Math.sin(t * w) / s;
  return [a[0] * ka + b[0] * kb, a[1] * ka + b[1] * kb, a[2] * ka + b[2] * kb];
}

/* The shortest path on the sphere, one point per degree of arc (at least 16). */
export function greatCircle(from, to) {
  const a = toVec(from.lat, from.lon), b = toVec(to.lat, to.lon), w = angle(a, b);
  const n = Math.max(16, Math.ceil(deg(w)));
  const points = Array.from({ length: n + 1 }, (_, i) => toLL(slerp(a, b, i / n)));
  return { a, b, w, n, km: w * R, points };
}

/* Where a reported position sits on a route: the fraction flown to its foot
 * on the great circle, and how far off the circle it is. The flown part ends
 * at the foot; a fix away from the route is never snapped onto it silently. */
export function onRoute(gc, pos) {
  if (gc.w < 1e-9) return { frac: 0, xtKm: 0 };
  const p = toVec(pos.lat, pos.lon), pole = norm(cross(gc.a, gc.b));
  const off = dot(p, pole);
  const foot = norm([p[0] - off * pole[0], p[1] - off * pole[1], p[2] - off * pole[2]]);
  const along = angle(gc.a, foot) * (dot(cross(gc.a, foot), pole) < 0 ? -1 : 1);
  return { frac: Math.max(0, Math.min(1, along / gc.w)), xtKm: Math.abs(Math.asin(Math.max(-1, Math.min(1, off)))) * R };
}

/* The point `km` from (lat, lon) on initial bearing `brg`. */
export function destination(lat, lon, brg, km) {
  const d = km / R, b = rad(brg), p1 = rad(lat), l1 = rad(lon);
  const p2 = Math.asin(Math.sin(p1) * Math.cos(d) + Math.cos(p1) * Math.sin(d) * Math.cos(b));
  const l2 = l1 + Math.atan2(Math.sin(b) * Math.sin(d) * Math.cos(p1), Math.cos(d) - Math.sin(p1) * Math.sin(p2));
  return { lat: deg(p2), lon: ((deg(l2) + 540) % 360) - 180 };
}

/* ── fixes ─────────────────────────────────────────────────────────────── */

export const AHEAD_S = 5;                       // clock skew forgiven before a time is "ahead"
export const MOTION = new Set(['live']);

export function judge(pos, prev, now, fresh) {
  if (!valid(pos)) return 'plan';
  const at = Number(pos.at);
  /* MUTANT */
  const age = (now - at) / 1000;
  if (age < -AHEAD_S) return 'ahead';
  if (age > fresh) return 'stale';
  const moved = valid(prev) && Number.isFinite(Number(prev.at)) && Number(prev.at) < at
    && (Number(prev.lat) !== Number(pos.lat) || Number(prev.lon) !== Number(pos.lon));
  return moved ? 'live' : 'held';
}

const clock = (ms) => new Date(ms).toISOString().slice(11, 19) + 'Z';

export function fixWords(state, pos, now) {
  const at = Number(pos?.at), age = (now - at) / 1000;
  switch (state) {
    case 'plan': return 'NO POSITION';
    case 'undated': return 'FIX UNDATED';
    case 'ahead': return `FIX ${clock(at)} IS AHEAD OF THIS CLOCK`;
    case 'stale': return age < 120 ? `LAST FIX ${clock(at)}` : `LAST FIX ${Math.floor(age / 60)} MIN AGO`;
    case 'held': return `FIX ${clock(at)}, NOT MOVED`;
    default: return `FIX ${clock(at)}`;
  }
}

/* The next moment any fix's state or words change, or null if none will. */
export function nextDue(fixes, now, fresh) {
  let due = Infinity;
  for (const pos of fixes) {
    if (!valid(pos)) continue;
    const at = Number(pos.at);
    if (!Number.isFinite(at) || pos.at === null || pos.at === '') continue;
    const age = (now - at) / 1000;
    let t;
    if (age < -AHEAD_S) t = at - AHEAD_S * 1000;
    else if (age <= fresh) t = at + fresh * 1000 + 1;
    else if (age < 120) t = at + 120000;
    else t = at + (Math.floor(age / 60) + 1) * 60000;
    if (t > now && t < due) due = t;
  }
  return Number.isFinite(due) ? due : null;
}

/* Remember the previous report per id, so "moved" is judged from two reports
 * and never assumed from one. Returns rows with their previous fix attached. */
export function remember(memory, rows, key = 'pos') {
  for (const r of rows) {
    const id = r.id ?? r.label;
    const pos = key ? r[key] : r;
    if (id === undefined || !valid(pos)) continue;
    const last = memory.last.get(id);
    if (last && Number(last.at) !== Number(pos.at)) memory.prev.set(id, last);
    memory.last.set(id, { lat: pos.lat, lon: pos.lon, at: pos.at });
  }
}

/* A scene file states times as SECONDS BEFORE NOW (`age`), like every scene in
 * this kit, so it reads the same whenever it is opened. `at` wins if given. */
export function dated(p, now) {
  if (!p || typeof p !== 'object' || p.at !== undefined || p.age === undefined) return p;
  const age = Number(p.age);
  return { ...p, at: Number.isFinite(age) ? now - age * 1000 : null };
}

/* ── countries ──────────────────────────────────────────────────────────── */

const shared = { data: null, listeners: new Set(), byUrl: new Map() };
const tell = () => { for (const fn of [...shared.listeners]) fn(); };

export function setCountries(data) { shared.data = data ?? null; tell(); }
export function getCountries() { return shared.data; }
export function onCountries(fn) { shared.listeners.add(fn); return () => shared.listeners.delete(fn); }

export function isCountries(d) {
  return !!d && typeof d === 'object' && Number.isFinite(d.q) && d.q > 0
    && Array.isArray(d.arcs) && Array.isArray(d.countries);
}

function loadCountries(url) {
  const href = new URL(url, document.baseURI).href;
  let e = shared.byUrl.get(href);
  if (e) return e;
  e = { state: 'loading', data: null, url };
  shared.byUrl.set(href, e);
  import(/* @vite-ignore */ href)
    .then((m) => { if (isCountries(m.default)) { e.state = 'ready'; e.data = m.default; } else e.state = 'unreadable'; },
      () => { e.state = 'failed'; })
    .finally(tell);
  return e;
}

/* What a map asked for and what it has: { want, state, data, url }. The map
 * passes its own `countries` attribute, so the attribute is read in the
 * element that declares it. */
export function countriesFor(el, wants, url) {
  if (!wants) return { want: false, state: 'none' };
  const judgeData = (d) => (d === null || d === undefined ? { want: true, state: 'missing' }
    : isCountries(d) ? { want: true, state: 'ready', data: d } : { want: true, state: 'unreadable' });
  if (el._countries !== undefined) return judgeData(el._countries);
  if (url) { const e = loadCountries(url); return { want: true, state: e.state, data: e.data, url }; }
  return judgeData(shared.data);
}

export function countriesRefusal(c) {
  switch (c.state) {
    case 'missing': return 'COUNTRIES NOT LOADED: outlines were asked for and none were given';
    case 'loading': return 'COUNTRIES LOADING';
    case 'failed': return `COUNTRIES FAILED TO LOAD: ${c.url}`;
    case 'unreadable': return 'COUNTRIES UNREADABLE: not outline data';
    default: return '';
  }
}

const decoded = new WeakMap();

/* Arcs as [lon, lat] points, and each country ring as a list of arc indices
 * (~i for an arc walked backwards). Decoded once per data object. */
export function decode(data) {
  let d = decoded.get(data);
  if (d) return d;
  const arcs = data.arcs.map((flat) => {
    const pts = [];
    let x = 0, y = 0;
    for (let i = 0; i + 1 < flat.length; i += 2) { x += flat[i]; y += flat[i + 1]; pts.push([x * data.q, y * data.q]); }
    return pts;
  });
  const rings = [];
  for (const c of data.countries) {
    for (const poly of (Array.isArray(c?.[2]) ? c[2] : [])) {
      for (const idx of (Array.isArray(poly) ? poly : [])) {
        const out = [];
        for (const i of idx) {
          const a = i < 0 ? arcs[~i]?.slice().reverse() : arcs[i];
          if (!a) continue;
          out.push(...(out.length ? a.slice(1) : a));
        }
        if (out.length > 2) rings.push(out);
      }
    }
  }
  d = { arcs, rings };
  decoded.set(data, d);
  return d;
}

/* ── labels ─────────────────────────────────────────────────────────────── */

/* Four slots around a mark, scored by overlap with labels already placed and
 * by running off the glass. HYSTERESIS OF ZERO (ov-map's rule): the slot a
 * label had last paint wins every tie, so labels move only when staying is
 * strictly worse. `u` is drawing units per screen pixel. */
export function placeLabel(ctx, key, x, y, chars, u, width) {
  const w = (chars * 6.2 + 4) * u, h = 24 * u;
  const slots = [[9, -3, false], [-9, -3, true], [9, 21, false], [-9, 21, true]];
  const box = ([dx, dy, left]) => [left ? x + dx * u - w : x + dx * u, y + (dy - 12) * u, w, h];
  const hit = (a, b) => a[0] < b[0] + b[2] && b[0] < a[0] + a[2] && a[1] < b[1] + b[3] && b[1] < a[1] + a[3];
  const score = (i) => {
    const b = box(slots[i]);
    // Off the glass on any side counts: a label above the top edge is clipped,
    // and its second line is the one that says whether the fix is stale.
    // A clipped label is worse than one touching another, so leaving the glass
    // outweighs any number of overlaps: it happens only when every slot is off.
    return ctx.boxes.reduce((s, o) => s + (hit(b, o) ? 1 : 0), 0)
      + (b[0] < ctx.x0 || b[0] + b[2] > ctx.x0 + width ? 100 : 0)
      + (ctx.height !== undefined && (b[1] < ctx.y0 || b[1] + b[3] > ctx.y0 + ctx.height) ? 100 : 0);
  };
  const prev = ctx.slots.get(key) ?? 0;
  let best = prev, bestScore = score(prev);
  for (let i = 0; i < slots.length; i++) { const s = score(i); if (s < bestScore) { best = i; bestScore = s; } }
  ctx.slots.set(key, best);
  ctx.boxes.push(box(slots[best]));
  const [dx, dy, left] = slots[best];
  return { x: x + dx * u, y: y + (dy - 7) * u, left };
}

export const fmtKm = (km) => `${Math.round(km).toLocaleString('en-US')} km`;
export const esc = (s) => String(s ?? '').replace(/[<>&"]/g, '');
